def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 98:
        return 'D'

    my_last, opp_last = history[-1]
    recent_len = n if n < 8 else 8
    recent_start = n - recent_len

    opp_d = 0
    recent_d = 0
    for i in range(n):
        if history[i][1] == 'D':
            opp_d += 1
            if i >= recent_start:
                recent_d += 1

    prev_opp = history[-2][1] if n >= 2 else 'C'

    hostile = (
        (opp_d >= 3 and recent_d >= 2 and opp_d >= n - opp_d) or
        (recent_d >= 4 and opp_d >= 3) or
        (opp_d >= 5 and recent_d >= 3)
    )

    if hostile:
        if opp_last == 'C' and prev_opp == 'C' and recent_d <= 2:
            return 'C'
        return 'D'

    if opp_last == 'D':
        if my_last == 'C':
            if opp_d <= 1:
                return 'C'
            return 'D'
        if prev_opp == 'D' and recent_d >= 3:
            return 'D'
        return 'C'

    return 'C'
